import numpy as np
import pandas as pd
import pytest

from rfm.scorer import compute_rfm, score_customers


@pytest.fixture
def transactions():
    return pd.DataFrame(
        {
            "customer_id": ["A", "A", "A", "B", "B", "C"],
            "transaction_date": pd.to_datetime(
                [
                    "2025-01-01",
                    "2025-02-01",
                    "2025-03-01",
                    "2025-06-01",
                    "2025-07-01",
                    "2024-08-01",
                ]
            ),
            "amount": [10.00, 20.00, 30.00, 100.00, 50.00, 5.00],
        }
    )


def test_compute_rfm_metrics(transactions):
    asof = pd.Timestamp("2025-08-15")
    rfm = compute_rfm(transactions, asof)

    assert rfm.loc["A", "recency_days"] == (asof - pd.Timestamp("2025-03-01")).days
    assert rfm.loc["A", "frequency"] == 3
    assert rfm.loc["A", "monetary"] == 60.00

    assert rfm.loc["B", "recency_days"] == (asof - pd.Timestamp("2025-07-01")).days
    assert rfm.loc["C", "frequency"] == 1


def test_scores_are_in_range_and_composite_weighted(transactions):
    scored = score_customers(compute_rfm(transactions, pd.Timestamp("2025-08-15")))
    for col in ("r", "f", "m"):
        assert scored[col].between(1, 5).all()

    expected = 0.5 * scored["r"] + 0.3 * scored["f"] + 0.2 * scored["m"]
    assert np.allclose(scored["composite"], expected.round(4))


def test_recency_scoring_direction(transactions):
    # A purchased most recently of the three -> best recency score.
    scored = score_customers(compute_rfm(transactions, pd.Timestamp("2025-08-15")))
    assert scored["r"]["A"] > scored["r"]["B"] > scored["r"]["C"]


def test_quintiles_cover_full_range():
    n = 100
    txs = pd.DataFrame(
        {
            "customer_id": [f"K{i:03d}" for i in range(n)],
            "transaction_date": [pd.Timestamp("2025-07-01")] * n,
            "amount": np.arange(float(n)),
        }
    )
    scored = score_customers(compute_rfm(txs, pd.Timestamp("2025-08-15")))
    assert set(scored["m"]) == {1, 2, 3, 4, 5}


def test_transactions_after_asof_rejected():
    txs = pd.DataFrame(
        {
            "customer_id": ["X"],
            "transaction_date": pd.to_datetime(["2025-09-01"]),
            "amount": [10.0],
        }
    )
    with pytest.raises(ValueError):
        compute_rfm(txs, pd.Timestamp("2025-08-15"))

